/* G40-607 — say WHO declined a payment.
 *
 * The backend now stores why a payment failed in the order's `stripe_error`
 * (helpers/decline_reason.js): Stripe's fraud check stopped it, the bank
 * declined it, the bank wants the customer to approve it, or no reason was
 * given. On order 66352 Stripe blocked a Link payment that the customer was
 * told her bank had refused.
 *
 * Words are John's Stage 1 pick A ("name who in the title", 10/15 10:26 AM
 * ET, pick doc https://claude.ai/artifact/Fa5yZGoPxANmXbASAhxfg6). The
 * website uses the same codes and words. */

export const DECLINE_REASON = Object.freeze({
  STRIPE_BLOCKED: "stripe_blocked",
  BANK_DECLINED: "bank_declined",
  NEEDS_APPROVAL: "needs_approval",
  PAYMENT_FAILED: "payment_failed",
});

const KNOWN = new Set(Object.values(DECLINE_REASON));

/* The order's stripe_error → a reason. null when the order has none (the
   caller keeps its older words); anything unrecognised, including the
   pre-G40-607 "User's bank denied transaction", reads as PAYMENT_FAILED. */
export function declineReasonFrom(stripeError) {
  if (!stripeError) return null;
  return KNOWN.has(stripeError) ? stripeError : DECLINE_REASON.PAYMENT_FAILED;
}

/* Sheet title + body parts. `label` is the method as shown ("Visa •••• 5613",
   "Link"); `bold` is rendered bold by the sheet. */
export function declineSheetCopy(reason, label) {
  switch (reason) {
    case DECLINE_REASON.STRIPE_BLOCKED:
      return {
        title: "Stripe stopped this payment",
        before: "Stripe, our payment processor, stopped your ",
        bold: label || "",
        after: `${label ? " " : ""}payment. Your bank wasn’t charged. Use a debit or credit card to keep this request.`,
      };
    case DECLINE_REASON.BANK_DECLINED:
      return {
        title: "Your bank declined this payment",
        before: "Your bank declined ",
        bold: label || "your card",
        after: ". Use another card, or call your bank, to keep this request.",
      };
    case DECLINE_REASON.NEEDS_APPROVAL:
      return {
        title: "Your bank needs to approve this payment",
        before: "",
        bold: "",
        after:
          "It can’t ask you while a worker is accepting. Use another card to keep this request.",
      };
    case DECLINE_REASON.PAYMENT_FAILED:
      return {
        title: "Your payment didn’t go through",
        before: "",
        bold: "",
        after:
          "Stripe didn’t give a reason. Use another card, or try again in a few minutes.",
      };
    default:
      return null;
  }
}

/* The home card's status line. null → the caller keeps its older line. */
export function declineHomeStatus(reason) {
  switch (reason) {
    case DECLINE_REASON.STRIPE_BLOCKED:
      return "Stripe stopped the payment · use another card";
    case DECLINE_REASON.BANK_DECLINED:
      return "Your bank declined the card · update payment info";
    case DECLINE_REASON.NEEDS_APPROVAL:
      return "Your bank needs to approve it · use another card";
    case DECLINE_REASON.PAYMENT_FAILED:
      return "Payment didn’t go through · update payment info";
    default:
      return null;
  }
}
